css:
button {
  background: #282936;
  padding: 10px 2rem;
  outline: 2.5px solid #FEBF00;
  outline-offset: 3px;
  border: 0;
  color: white;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  font-size: 1rem;
  border-radius: 100rem;
  transition: 0.4s;
  font-weight: 600;
}

button:hover {
  outline-offset: 4.5px;
  background: #FEBF00;
  font-size: 1.1rem;
}
